/**
 * Calendar's states fixture in element form, with the React fixture's entry
 * names, so a contract's `when <state>` names the same entry in every shell. Each
 * entry is the markup a page writes, and what its script sets once the elements
 * are defined.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`. Never edit it by hand.
 */
import type * as zag from '@zag-js/date-picker'

import type { ComponentStates } from '@polymorph/elements'

import './Calendar'

export const states: ComponentStates = {
  component: 'Calendar',
  entries: [
    {
      name: 'month with selection',
      html: `<poly-calendar default-value="2026-07-15" aria-label="Due date"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
    {
      name: 'today visible',
      html: `<poly-calendar aria-label="Due date, this month"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
    {
      name: 'min/max bounds',
      html: `<poly-calendar default-value="2026-07-15" min-value="2026-07-10" max-value="2026-07-20" aria-label="Due date, within a narrow range"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
    {
      name: 'unavailable dates',
      html: `<poly-calendar default-value="2026-07-15" aria-label="Due date, weekdays only"></poly-calendar>`,
      subject: 'poly-calendar',
      setup: (find) => {
        const e0 = find('poly-calendar', 0)
        e0.isDateUnavailable = (date: zag.CalendarDate) =>
          [0, 6].includes(date.toDate('UTC').getUTCDay())
      },
      expect: { role: 'application' },
    },
    {
      name: 'week start override',
      html: `<poly-calendar default-value="2026-07-15" first-day-of-week="1" aria-label="Due date, weeks from Monday"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
    {
      name: 'another locale',
      html: `<poly-calendar default-value="2026-07-15" locale="de-DE" aria-label="Fälligkeitsdatum"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
    {
      name: 'disabled',
      html: `<poly-calendar disabled default-value="2026-07-15" aria-label="Due date, unavailable"></poly-calendar>`,
      subject: 'poly-calendar',
      expect: { role: 'application' },
    },
  ],
}
